import fs from 'fs';
import path from 'path';
import Handlebars from 'handlebars';
import ejs from 'ejs';
import { Page } from './types';

export const DEFAULT_TEMPLATES_DIR = './templates';
export const DEFAULT_PAGE_TEMPLATE_NAME = 'default';
export const DEFAULT_LAYOUT_NAME = 'default';

const TEMPLATE_RE = /\.(hbs|ejs)$/i;

export interface TemplateContext {
  page: Record<string, unknown>;
  title: string;
  date?: string;
  tags: string[];
  content: string;
  body?: string;
  pages?: Page[];
  site?: Record<string, unknown>;
  [key: string]: unknown;
}

interface TemplateSource {
  source: string;
  ext: string;
}

function listTemplateFiles(dir: string): string[] {
  if (!fs.existsSync(dir)) {
    return [];
  }
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && TEMPLATE_RE.test(entry.name))
    .map((entry) => path.join(dir, entry.name))
    .sort();
}

function nameWithoutExt(filePath: string): string {
  const base = path.basename(filePath);
  return base.replace(/\.(hbs|ejs)$/i, '');
}

export function pageToContext(page: Page, body?: string): TemplateContext {
  const pageData: Record<string, unknown> = {
    ...(page.data ?? {}),
    slug: page.slug,
    title: page.title,
    date: page.date,
    tags: page.tags,
    content: page.content,
    template: page.template,
    layout: page.layout,
  };
  return {
    page: pageData,
    title: page.title,
    date: page.date,
    tags: page.tags,
    content: page.content,
    body,
  };
}

export class TemplateEngine {
  readonly templatesDir: string;
  readonly enabled: boolean;

  private pageTemplates = new Map<string, TemplateSource>();
  private layouts = new Map<string, TemplateSource>();
  private indexTemplate?: TemplateSource;

  constructor(templatesDir: string) {
    this.templatesDir = path.resolve(templatesDir);
    this.enabled = fs.existsSync(this.templatesDir);
    if (this.enabled) {
      this.load();
    }
  }

  private load(): void {
    const partialsDir = path.join(this.templatesDir, 'partials');
    for (const file of listTemplateFiles(partialsDir)) {
      const source = fs.readFileSync(file, 'utf8');
      Handlebars.registerPartial(nameWithoutExt(file), source);
    }

    const layoutsDir = path.join(this.templatesDir, 'layouts');
    for (const file of listTemplateFiles(layoutsDir)) {
      this.layouts.set(nameWithoutExt(file), {
        source: fs.readFileSync(file, 'utf8'),
        ext: path.extname(file),
      });
    }

    for (const file of listTemplateFiles(this.templatesDir)) {
      const name = nameWithoutExt(file);
      if (name === 'index') {
        this.indexTemplate = {
          source: fs.readFileSync(file, 'utf8'),
          ext: path.extname(file),
        };
      } else {
        this.pageTemplates.set(name, {
          source: fs.readFileSync(file, 'utf8'),
          ext: path.extname(file),
        });
      }
    }
  }

  hasTemplate(name: string): boolean {
    return this.pageTemplates.has(name);
  }

  hasLayout(name: string): boolean {
    return this.layouts.has(name);
  }

  render(source: string, ext: string, context: TemplateContext): string {
    if (ext.toLowerCase() === '.ejs') {
      return ejs.render(source, context, {
        filename: path.join(this.templatesDir, 'layout.ejs'),
        root: this.templatesDir,
        views: [this.templatesDir],
      });
    }
    return Handlebars.compile(source)(context);
  }
}

export function renderTemplateFile(
  templatesDir: string,
  relativePath: string,
  context: TemplateContext,
): string {
  const full = path.resolve(templatesDir, relativePath);
  const ext = path.extname(full);
  return new TemplateEngine(templatesDir).render(
    fs.readFileSync(full, 'utf8'),
    ext,
    context,
  );
}

import fs from 'fs';
import path from 'path';
import { Page } from './types';
import { parseMarkdown, slugify } from './markdown';
import {
  DEFAULT_TEMPLATES_DIR,
  DEFAULT_PAGE_TEMPLATE_NAME,
  DEFAULT_LAYOUT_NAME,
  TemplateEngine,
  pageToContext,
} from './template';

const MARKDOWN_RE = /\.(md|markdown)$/i;

export interface BuildSiteOptions {
  templatesDir?: string;
}

export function collectMarkdownFiles(contentDir: string): string[] {
  if (!fs.existsSync(contentDir)) {
    return [];
  }
  const results: string[] = [];
  const walk = (dir: string): void => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (entry.isFile() && MARKDOWN_RE.test(entry.name)) {
        results.push(full);
      }
    }
  };
  walk(contentDir);
  return results.sort();
}

export function readPages(contentDir: string): Page[] {
  return collectMarkdownFiles(contentDir).map((filePath) => {
    const slug = slugify(path.basename(filePath));
    const raw = fs.readFileSync(filePath, 'utf8');
    const doc = parseMarkdown(slug, raw);
    return {
      slug: doc.slug,
      title: doc.title,
      date: doc.date,
      tags: doc.tags,
      template: doc.template,
      layout: doc.layout,
      data: doc.data,
      content: doc.content,
    };
  });
}

export function sortPages(pages: Page[]): Page[] {
  return [...pages].sort((a, b) => {
    const da = a.date ? Date.parse(a.date) : -Infinity;
    const db = b.date ? Date.parse(b.date) : -Infinity;
    if (da !== db) {
      return db - da;
    }
    return a.title.localeCompare(b.title);
  });
}

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function renderPageBody(page: Page): string {
  const dateTag = page.date
    ? `    <p class="date"><time datetime="${escapeHtml(page.date)}">${escapeHtml(
        page.date,
      )}</time></p>\n`
    : '';
  const tags = page.tags.length
    ? `    <p class="tags">${page.tags
        .map((t) => `<span class="tag">${escapeHtml(t)}</span>`)
        .join(' ')}</p>\n`
    : '';
  return `  <article>
    <h1>${escapeHtml(page.title)}</h1>
${dateTag}${tags}    ${page.content}
  </article>`;
}

export function renderPage(page: Page): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(page.title)}</title>
</head>
<body>
${renderPageBody(page)}
  <p><a href="index.html">&larr; Back to index</a></p>
</body>
</html>
`;
}

export function renderIndex(pages: Page[]): string {
  const items = pages
    .map((p) => {
      const date = p.date ? ` <time>${escapeHtml(p.date)}</time>` : '';
      const tags = p.tags.length
        ? ` <span class="tags">${p.tags
            .map((t) => `#${escapeHtml(t)}`)
            .join(' ')}</span>`
        : '';
      return `    <li><a href="${encodeURIComponent(p.slug)}.html">${escapeHtml(
        p.title,
      )}</a>${date}${tags}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Index</title>
</head>
<body>
  <h1>Pages</h1>
  <ul>
${items}
  </ul>
</body>
</html>
`;
}

export function renderPageWithEngine(page: Page, engine: TemplateEngine): string {
  const name = page.template ?? DEFAULT_PAGE_TEMPLATE_NAME;
  const template = engine.pageTemplates.get(name);
  let bodyHtml: string;
  if (template) {
    bodyHtml = engine.render(template.source, template.ext, pageToContext(page));
  } else {
    bodyHtml = renderPageBody(page);
  }

  const layoutName = page.layout ?? DEFAULT_LAYOUT_NAME;
  const layout = engine.layouts.get(layoutName);
  if (layout) {
    return engine.render(
      layout.source,
      layout.ext,
      pageToContext(page, bodyHtml),
    );
  }
  return bodyHtml;
}

export function renderIndexWithEngine(pages: Page[], engine: TemplateEngine): string {
  if (engine.indexTemplate) {
    return engine.render(engine.indexTemplate.source, engine.indexTemplate.ext, {
      page: {},
      title: 'Index',
      date: undefined,
      tags: [],
      content: '',
      pages,
      site: { pages },
    });
  }
  return renderIndex(pages);
}

export function buildSite(
  contentDir: string,
  outputDir: string,
  options: BuildSiteOptions = {},
): Page[] {
  const pages = sortPages(readPages(contentDir));
  const templatesDir = options.templatesDir ?? DEFAULT_TEMPLATES_DIR;
  const engine = new TemplateEngine(templatesDir);

  fs.mkdirSync(outputDir, { recursive: true });
  fs.writeFileSync(
    path.join(outputDir, 'index.html'),
    engine.enabled ? renderIndexWithEngine(pages, engine) : renderIndex(pages),
    'utf8',
  );
  for (const page of pages) {
    fs.writeFileSync(
      path.join(outputDir, `${page.slug}.html`),
      engine.enabled ? renderPageWithEngine(page, engine) : renderPage(page),
      'utf8',
    );
  }
  return pages;
}

